import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";

export async function POST(
  request: NextRequest,
  context: { params: { id: string } }
) {
  try {
    const routineId =
      context?.params?.id ||
      request.nextUrl.pathname.split("/api/routines/")[1]?.split("/")[0];

    if (!routineId) {
      return NextResponse.json(
        { error: "Routine ID is required" },
        { status: 400 }
      );
    }

    const session = await auth();

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const body = await request.json();
    const { productId, timeOfDay } = body;

    if (!productId || !timeOfDay) {
      return NextResponse.json(
        { error: "Product ID and time of day are required" },
        { status: 400 }
      );
    }

    const normalizedTime = String(timeOfDay).toUpperCase();

    const routine = await prisma.routine.findFirst({
      where: {
        id: routineId,
        userId: session.user.id,
      },
    });

    if (!routine) {
      return NextResponse.json(
        { error: "Routine not found" },
        { status: 404 }
      );
    }

    const existing = await prisma.routineProduct.findFirst({
      where: {
        routineId,
        productId,
        timeOfDay: normalizedTime,
        removedAt: null,
      },
    });

    if (existing) {
      return NextResponse.json(
        { error: "Product already in this routine section" },
        { status: 400 }
      );
    }

    const routineProduct = await prisma.routineProduct.create({
      data: {
        routineId,
        productId,
        timeOfDay: normalizedTime,
      },
      include: {
        product: true,
      },
    });

    return NextResponse.json({ routineProduct }, { status: 201 });
  } catch (error) {
    console.error("Error adding product to routine:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

export async function DELETE(
  request: NextRequest,
  context: { params: { id: string } }
) {
  try {
    const routineId =
      context?.params?.id ||
      request.nextUrl.pathname.split("/api/routines/")[1]?.split("/")[0];

    if (!routineId) {
      return NextResponse.json(
        { error: "Routine ID is required" },
        { status: 400 }
      );
    }

    const session = await auth();

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { searchParams } = new URL(request.url);
    const productId = searchParams.get("productId");
    const timeOfDay = searchParams.get("timeOfDay");

    if (!productId) {
      return NextResponse.json(
        { error: "Product ID is required" },
        { status: 400 }
      );
    }

    // Verify routine belongs to user
    const routine = await prisma.routine.findFirst({
      where: {
        id: routineId,
        userId: session.user.id,
      },
    });

    if (!routine) {
      return NextResponse.json(
        { error: "Routine not found" },
        { status: 404 }
      );
    }

    // Remove product from routine
    await prisma.routineProduct.updateMany({
      where: {
        routineId,
        productId,
        removedAt: null,
        ...(timeOfDay
          ? { timeOfDay: String(timeOfDay).toUpperCase() }
          : {}),
      },
      data: {
        removedAt: new Date(),
      },
    });

    return NextResponse.json({ message: "Product removed from routine" });
  } catch (error) {
    console.error("Error removing product from routine:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}
